    if (m.startsWith('pv'))      return { table: 'pv_performance_hourly', col: 'avg_power_kw' };
    if (m.startsWith('weather')) return { table: 'weather_hourly',        col: 'avg_temperature_c' };
    if (m.startsWith('traffic')) return { table: 'traffic_pattern_hourly',col: 'traffic_index' };
    return { table: 'net_grid_hourly', col: 'net_grid_kw' };
}

