    msg._sql = `SELECT * FROM "gold"."anomaly_candidates" ORDER BY hour DESC LIMIT 200`;
    msg._fapShape = 'anomalies';
    msg._meta = { table: 'gold.anomaly_candidates' };
    return [msg, null];
