    const objs = rows.map(r => { const o = {}; for (let i = 0; i < cols.length; i++) o[cols[i]] = r[i]; return o; });
    const baseMeta = Object.assign({ source: 'gold', generated_at: new Date().toISOString(), row_count: objs.length }, msg._meta || {});
