    if (msg._fapShape === 'trends') {
        const series = objs.map(o => ({ timestamp: o.hour, value: Number(o.value) || 0 }));
        const values = series.map(s => s.value);
        const min = values.length ? Math.min(...values) : 0;
        const max = values.length ? Math.max(...values) : 0;
        const avg = values.length ? values.reduce((a, b) => a + b, 0) / values.length : 0;
        const trend = values.length < 2 ? 'stable' : (values[values.length-1] > values[0] ? 'up' : values[values.length-1] < values[0] ? 'down' : 'stable');
        data = { series, min, max, avg, trend, metadata: baseMeta };
    } else if (msg._fapShape === 'correlations') {
        const a = objs.map(o => Number(o.v_a) || 0);
        const b = objs.map(o => Number(o.v_b) || 0);
        const n = a.length;
        const meanA = n ? a.reduce((s,v) => s+v, 0) / n : 0;
        const meanB = n ? b.reduce((s,v) => s+v, 0) / n : 0;
        let num = 0, denA = 0, denB = 0;
        for (let i = 0; i < n; i++) { num += (a[i]-meanA)*(b[i]-meanB); denA += (a[i]-meanA)**2; denB += (b[i]-meanB)**2; }
        const r = denA && denB ? num / Math.sqrt(denA * denB) : 0;
